package compatgen

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"sort"
	"strings"

	"mvdan.cc/sh/v3/syntax"
)

// Bash parses every function it reads: the generated files hold some 80 KB
// of them, about 5 ms of each load, though a shell calls few of them. So a
// long function is generated as a one-line stand-in, and its definition
// goes to lib/compat/cold/NAME.sh, which __gash_cold (bootstrap.sh) reads
// at the first call:
//
//	# shellcheck disable=SC2120
//	NAME() { __gash_cold NAME HASH && "${FUNCNAME[0]}" "$@"; }
//
// HASH is the definition's: a cold file of another Gash version (the tree
// upgraded under a running shell) is refused, never mixed in.

// ColdDir holds the cold definitions, relative to the tree.
const ColdDir = "lib/compat/cold/"

// lazyMin is the shortest definition worth a cold file: the stand-in
// itself is some 70 bytes of parsing.
const lazyMin = 400

// hot are the functions every load or every delegated call runs: they stay
// whole (TestColdNotAtLoad proves no load reads a cold file).
var hot = map[string]bool{
	"__gash_source": true, "__gash_time_record": true, "__gash_require_bash_message": true,
	"__gash_bin_resolve": true, "__gash_cold": true, "__gash_call": true, "__gash_export_state": true,
	"__gash_srv_ready": true, "__gash_srv_call": true, "__gash_srv_decls": true, "__gash_srv_stop": true,
	"__gash_locale_utf8": true, "__gash_color_env_ok": true, "__gash_apply_env_settings": true,
	"__gash_symbols_now": true, "__gash_stdout_tty": true, "__gash_enable_completion": true,
}

// lazyFile tells the generated files whose long functions go cold.
func lazyFile(path string) bool {
	return path == "gash.sh" || path == "bash_completion" || path == "lib/compat/bootstrap.sh" ||
		strings.HasPrefix(path, "lib/core/") || strings.HasPrefix(path, "lib/modules/")
}

// coldDef is a definition taken out of a generated file (from).
type coldDef struct {
	from, hash string
	def        []byte
}

// lazify replaces the long top-level function definitions of src (the
// file path) by stand-ins and adds them to cold, by name. A name defined
// in two files must have the same definition in both (a module shim and
// gash.sh share the stubs).
func lazify(path string, src []byte, cold map[string]coldDef) ([]byte, error) {
	f, err := syntax.NewParser(syntax.Variant(syntax.LangBash)).Parse(bytes.NewReader(src), path)
	if err != nil {
		return nil, fmt.Errorf("compatgen: %s: %w", path, err)
	}
	var out bytes.Buffer
	last := 0
	for _, st := range f.Stmts {
		fd, ok := st.Cmd.(*syntax.FuncDecl)
		if !ok || st.Negated || st.Background || st.Coprocess || len(st.Redirs) > 0 || len(fd.Body.Redirs) > 0 || fd.RsrvWord || !fd.Parens {
			continue
		}
		name := fd.Name.Value
		start, end := int(st.Pos().Offset()), int(st.End().Offset())
		def := src[start:end]
		if hot[name] || len(def) < lazyMin || st.Pos().Col() != 1 ||
			!bytes.HasPrefix(def, []byte(name+"() {")) || (end < len(src) && src[end] != '\n') {
			continue
		}
		sum := sha256.Sum256(def)
		hash := hex.EncodeToString(sum[:4])
		if prev, dup := cold[name]; dup && !bytes.Equal(prev.def, def) {
			return nil, fmt.Errorf("compatgen: %s: %s is defined differently in %s", path, name, prev.from)
		} else if !dup {
			cold[name] = coldDef{from: path, hash: hash, def: def}
		}
		out.Write(src[last:start])
		// (SC2120: a caller that passes no arguments is fine.)
		fmt.Fprintf(&out, "# shellcheck disable=SC2120\n"+`%s() { __gash_cold %s %s && "${FUNCNAME[0]}" "$@"; }`, name, name, hash)
		last = end
	}
	out.Write(src[last:])
	return out.Bytes(), nil
}

// coldFiles returns the cold definitions as files, in name order: a
// header whose last word is the hash, then the definition.
func coldFiles(cold map[string]coldDef) []File {
	names := make([]string, 0, len(cold))
	for n := range cold {
		names = append(names, n)
	}
	sort.Strings(names)
	files := make([]File, 0, len(names))
	for _, n := range names {
		c := cold[n]
		var b bytes.Buffer
		fmt.Fprintf(&b, "# shellcheck shell=bash\n# Generated by `gash __compat generate` from %s: do not edit. %s\n%s\n", c.from, c.hash, c.def)
		files = append(files, File{Path: ColdDir + n + ".sh", Mode: 0o644, Data: b.Bytes()})
	}
	return files
}
